// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testRegression_property() public {
        address user = address(0x1234);
        uint256 depositAmount = 1000 wei;

        vm.deal(user, depositAmount);

        vm.prank(user);
        c.deposit{value: depositAmount}();

        vm.deal(user, depositAmount);
        vm.prank(user);
        bool success = false;
        try c.deposit{value: depositAmount}() {
            success = true;
        } catch {
            success = false;
        }




















        vm.deal(user, 1 ether);
        vm.prank(user);
        bool refReverts = false;
        try c.deposit{value: 0}() {
            refReverts = false;
        } catch {
            refReverts = true;
        }
        assertTrue(refReverts, "Expected revert on zero-value deposit in reference");
    }
}
